 const nav=[['overview','Overview','grid'],['personal','My Finance','wallet'],['business','Business','building'],['inventory','Inventory','box'],['sales','Sales & POS','cart'],['accounting','Accounting','wallet'],['billing','Plans & Billing','wallet'],['settings','Settings','settings'],...(isPlatformAdmin?[['admin','Timzee Admin','shield'] as const]:[])] as const;
